"""Patch the android/ folder generated by `flutter create` for the Erriwaya Mushaf app."""
import os
import re
import sys

root = sys.argv[1] if len(sys.argv) > 1 else "."
main = os.path.join(root, "android", "app", "src", "main")
manifest_path = os.path.join(main, "AndroidManifest.xml")

with open(manifest_path, encoding="utf-8") as f:
    m = f.read()

m = re.sub(r'android:label="[^"]*"', 'android:label="مصحف الرواية"', m, count=1)
if "android.permission.INTERNET" not in m:
    m = m.replace("<application", '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1)
# تشغيل التلاوة عبر http(s) من خوادم التلاوات
if "usesCleartextTraffic" not in m:
    m = m.replace("<application", '<application android:usesCleartextTraffic="true"', 1)
with open(manifest_path, "w", encoding="utf-8") as f:
    f.write(m)

res = os.path.join(main, "res")
os.makedirs(os.path.join(res, "values"), exist_ok=True)
with open(os.path.join(res, "values", "erriwaya_colors.xml"), "w", encoding="utf-8") as f:
    f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n'
            '    <color name="erriwaya_green">#004A49</color>\n</resources>\n')
for name in ("drawable/launch_background.xml", "drawable-v21/launch_background.xml"):
    p = os.path.join(res, name)
    if os.path.exists(p):
        with open(p, "w", encoding="utf-8") as f:
            f.write('<?xml version="1.0" encoding="utf-8"?>\n'
                    '<layer-list xmlns:android="http://schemas.android.com/apk/res/android">\n'
                    '    <item android:drawable="@color/erriwaya_green" />\n</layer-list>\n')
print(open(manifest_path, encoding="utf-8").read())

# مفتاح توقيع ثابت حتى تُثبَّت كل نسخة جديدة فوق السابقة.
gradle_kts = os.path.join(root, "android", "app", "build.gradle.kts")
signing = '''    signingConfigs {
        create("erriwaya") {
            storeFile = file("../../android-ci/debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }

    buildTypes {'''
with open(gradle_kts, encoding="utf-8") as f:
    g = f.read()
if 'create("erriwaya")' not in g:
    assert "    buildTypes {" in g, "buildTypes block not found"
    g = g.replace("    buildTypes {", signing, 1)
    g = g.replace('signingConfig = signingConfigs.getByName("debug")',
                  'signingConfig = signingConfigs.getByName("erriwaya")')
    assert 'getByName("erriwaya")' in g, "release signingConfig not patched"
g = re.sub(r"minSdk = flutter\.minSdkVersion", "minSdk = 23", g)
with open(gradle_kts, "w", encoding="utf-8") as f:
    f.write(g)
print(g)
